import re,os,base64
if not os.path.exists('www/index.html'):
    os.chdir('/workspaces/PORTAL_CONDUCTOR/portal')
p='www/index.html'
s=open(p,encoding='utf-8').read()
if 'id="v38-style"' in s:
    print('v3.8 ya aplicado'); raise SystemExit
IMG=''
open('www/header-jahapy.jpg','wb').write(base64.b64decode(IMG))
rep=[]
new='<header class="header hdr-jahapy"><button class="menu-btn" aria-label="Abrir menú" onclick="openSideMenu()">☰</button><div class="brandbox"><div class="brand">Portal del Conductor</div></div><div class="jahapy-tag" aria-hidden="true"><span>Jahapy</span><i></i></div></header>'
s,n=re.subn(r'<header class="header"><button class="menu-btn"[^>]*>☰</button><div class="brandbox"><div class="brand">Super Portal del Conductor</div></div><img src="data:[^"]*"[^>]*></header>',lambda m:new,s,count=1)
rep.append(('cabecera',n))
css='''<style id="v38-style">
.app .header.hdr-jahapy{position:relative!important;display:block!important;height:125px!important;min-height:125px!important;padding:0!important;overflow:hidden!important;background:linear-gradient(180deg,rgba(3,10,28,.62) 0%,rgba(3,10,28,.08) 50%,rgba(3,10,28,.42) 100%),url(header-jahapy.jpg) center 60%/cover no-repeat,#07131e!important;border:1px solid #3fc8ff88!important}
.app .header.hdr-jahapy .menu-btn{position:absolute!important;left:10px!important;top:10px!important;z-index:5;background:rgba(7,18,40,.55)!important;border-color:#ffffff55!important}
.app .header.hdr-jahapy .brandbox{position:absolute!important;left:62px!important;top:14px!important;right:8px!important;min-width:0!important;flex:none!important;z-index:5;display:block!important}
.app .header.hdr-jahapy .brand{font-size:clamp(18px,5.6vw,25px)!important;line-height:1.05!important;white-space:nowrap!important;color:#fff!important;font-weight:900!important;text-shadow:0 2px 6px rgba(0,0,0,.85),0 0 14px rgba(0,30,90,.7)!important}
.jahapy-tag{position:absolute;right:12px;bottom:9px;z-index:5;text-align:center;line-height:1}
.jahapy-tag span{display:block;font-size:clamp(24px,7.4vw,32px);font-weight:900;font-style:italic;color:#fff;letter-spacing:.3px;text-shadow:0 0 3px #0a2a74,0 0 6px #0a2a74,0 2px 8px rgba(0,0,0,.8)}
.jahapy-tag i{display:block;height:4px;margin-top:3px;border-radius:3px;background:linear-gradient(90deg,#d52b1e 0 33.3%,#fff 33.3% 66.6%,#0038a8 66.6%);box-shadow:0 0 5px rgba(0,0,0,.6)}
</style>'''
s,n=re.subn(r'v3\.\d lector','v3.8 lector',s); rep.append(('version',n))
s=s.rstrip()+'\n'+css+'\n'
open(p,'w',encoding='utf-8').write(s)
for l,n in rep: print(f'{l}: {n}')
print('v3.8 aplicado')
